Method.Implementation:
	$$$TRACE("Inside Select Method")
	set pResponse = ##class(EnsLib.SQL.Snapshot).%New()
	// So this get all the records
	set pResponse.MaxRowsToGet = -1
	set tSQL = "SELECT "_pRequest.ColumnName_" FROM "_pRequest.TableName_" WHERE "_pRequest.WhereClause


 	set tSC = ..Adapter.ExecuteQuery(.pResponse,tSQL)

	if tSC = 1
	{
		$$$TRACE("Successfully executed Query:"_tSQL)
	}
	else
	{
		$$$TRACE("Failed to execute Query:"_tSQL)	
	}

	Quit tSC
